const AdmZip=require("adm-zip"),fse=require("fs-extra");async function unzip(e,n){return console.warn("@@@@@ [unzip]",e),new Promise((t,i)=>{try{setTimeout(()=>{const s=new AdmZip(e),o=s.getEntries();for(const e of o){const n=e.entryName;/^\.\.(\\|\/)+/.test(n)&&i("illegal access"),/(\\|\/)+\.\.(\\|\/)+/.test(n)&&i("illegal access"),/(\\|\/)+\.\.$/.test(n)&&i("illegal access")}s.extractAllTo(n,!0),t({})},200)}catch(e){console.warn("@@@@@ [unzip] Fail. Error:",e),i(e)}})}function genZip(e,n){const t=new AdmZip;t.addLocalFolder(e),fse.writeFileSync(n,t.toBuffer())}module.exports={unzip:unzip,genZip:genZip};